import{z as i,x as n,o as B,c as d,q as t,j as r,D as e,d as l,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"流处理模型","description":"","frontmatter":{"title":"流处理模型","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-model.md","filePath":"cs/stream-model.md","lastUpdated":1791413859000}'),p={name:"cs/stream-model.md"};function m(h,E,c,C,D,f){const A=n("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="流处理模型" tabindex="-1">流处理模型 <a class="header-anchor" href="#流处理模型" aria-label="Permalink to &quot;流处理模型&quot;">​</a></h1><div class="epigraph"><p>数据要么有界要么无界。批处理是流处理在「输入恰好完成」时的特例，而不是相反；把无界数据硬塞进「跑完再说」的框架，丢掉的不是效率，是结果本身的定义。</p><footer>—— 据 Akidau et al., The Dataflow Model, VLDB 2015；Streaming Systems, O&#39;Reilly 2018 整理</footer></div><p><a href="/cs/cg-debugging-map">上一课</a>给「编译器后端深化」收束：错译找第一个改坏语义的 pass，漏优化找机会消失的那一步，化简、二分与翻译验证各司其职——八课一句总纲，每一层都在信息丢掉之前做决定。编译器的账结了，数据库这边还剩一个默认要翻：整条数据库主干——从<a href="/cs/relational-model">关系模型</a>到<a href="/cs/two-pc">两阶段提交</a>——默认同一件事：数据有界，行先落盘，查询后到。本课是「流处理」课程的第一课，前提反过来：数据无界，记录到达即算，永远没有「跑完」。本课钉流处理模型的最小词汇——记录与事件时间、算子与状态、结果作为持续修正的 changelog；窗口、watermark、恰好一次都建在它上面。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有界数据上，计算是一个函数：输入完成，一次求值，答案确定。无界数据没有「完成」：计数、join、聚合在任意时刻都必须给出可辩护的答案，且答案随新记录修正。三个问题立刻出现：结果定义在哪根时间轴上——事件发生的时间，还是被处理的时刻；记录乱序、迟到时，先前发出去的答案要不要改；机器挂在两条记录之间，已算的部分怎么办。缺口不是「能不能处理数据」，而是先立一套模型，让正确性、延迟、成本三者可以分开陈述，而不是搅在一个引擎名里。</p><p><span class="marginnote">MillWheel（VLDB 2013）把时间戳交给用户数据自己携带，计算只认时间戳不认到达时刻；Dataflow 模型（VLDB 2015）再把窗口、触发器、累积方式拆成互相正交的决定。今天各引擎的词汇表基本是这两篇的展开。</span></p><p><span class="marginnote">常见误区：「无界」说的不是数据量大到装不下，而是没有完成时刻——一条每秒只来一条的计数流，内存占用恒定，照样是无界流；反过来，昨天的全量日志再大也是有界的。有无界由答案的定义决定，不由数据量决定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型分四步钉。第一，记录携带事件时间戳：时间属于数据，不属于处理它的机器。第二，计算是有状态或无状态算子组成的 DAG：记录沿边流动，边上的通道必须有限、可恢复。第三，输入可重放：无界流上的故障恢复要求「同一段输入可以再来一遍」，这正是分区追加日志提供的性质——<a href="/cs/kafka-log">Kafka 日志</a>的按键有序与偏移回退因此是流系统的标准源，而不只是消息队列的实现细节。第四，结果是 changelog 而非表：下游要么消费修订，要么读快照，<a href="/cs/lakehouse-table-format">湖仓表格式</a>与 <a href="/cs/logical-replication-cdc">CDC</a> 是它的两个落点。</p>',9)),(B(),r(s,null,{default:e(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%EF%BC%9A%E5%8F%AF%E9%87%8D%E6%94%BE%E7%9A%84%E5%88%86%E5%8C%BA%E6%97%A5%E5%BF%97%22%5D%20--%3E%20OP1%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E7%AE%97%E5%AD%90%EF%BC%9A%E5%8F%98%E6%8D%A2%E3%80%81%E8%BF%87%E6%BB%A4%22%5D%0A%20%20OP1%20--%3E%20OP2%5B%22%E6%9C%89%E7%8A%B6%E6%80%81%E7%AE%97%E5%AD%90%EF%BC%9A%E6%8C%89%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E8%81%9A%E5%90%88%22%5D%0A%20%20OP2%20--%3E%20SNK%5B%22%E6%B1%87%EF%BC%9A%E6%8C%81%E7%BB%AD%E4%BF%AE%E6%AD%A3%E7%9A%84%E7%BB%93%E6%9E%9C%20changelog%22%5D%0A%20%20B%5B%22%E6%9C%89%E7%95%8C%E9%9B%86%E5%90%88%22%5D%20--%3E%7C%22%E6%89%B9%E6%98%AF%E7%89%B9%E4%BE%8B%EF%BC%9A%E5%AE%8C%E6%88%90%E5%90%8E%E4%B8%80%E6%AC%A1%E6%B1%82%E5%80%BC%22%7C%20OP2%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"changelog 的意思就是「不改旧答案，只追加新答案」：第一版说下单量 42，迟到记录到齐后追加一版 47——下游永远读「最新一版」，而不是苦等一个不存在的「最终一版」。数据库的 WAL 与逻辑复制，落点都是同一种结构。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"事件时间与处理时间是两根独立的钟。两者之差没有上界：消费落后、重试、分区倾斜都能把「事件发生」与「记录被算」拉开几分钟甚至几小时。模型必须让两者分离陈述，否则「昨天的下单量」这个问题的答案随系统负载漂移——按处理时间聚合，重放历史数据得到的是「当时算多少」，不是「当时发生多少」，这是第一批流系统最常见的翻车点。无状态算子只变换记录，状态放在键上；有状态算子把历史压进状态，状态的存活期与回收条件是后两课的主题。正确性换延迟：早发射是近似，后续修订收敛到正确值；坚持等「全了再发」，无界流上永远等不到。批处理把全部修订一次性给全，流处理把修订摊在时间轴上——两者的结果在收敛后应当无差，差了就是语义实现错了。",-1)),(B(),r(s,null,{default:e(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%EF%BC%9A%E8%AE%B0%E5%BD%95%E8%87%AA%E5%B8%A6%E7%9A%84%E9%92%9F%22%5D%20--%3E%20WIN%5B%22%E6%8C%89%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E5%BC%80%E7%AA%97%E8%81%9A%E5%90%88%22%5D%0A%20%20PRC%5B%22%E5%A4%84%E7%90%86%E6%97%B6%E9%97%B4%EF%BC%9A%E6%9C%BA%E5%99%A8%E7%9A%84%E9%92%9F%22%5D%20--%3E%20SKEW%5B%22%E4%B9%B1%E5%BA%8F%E4%B8%8E%E8%BF%9F%E5%88%B0%EF%BC%9A%E4%B8%A4%E9%92%9F%E4%B9%8B%E5%B7%AE%E6%97%A0%E4%B8%8A%E7%95%8C%22%5D%0A%20%20WIN%20--%3E%20EARLY%5B%22%E8%A7%A6%E5%8F%91%EF%BC%9A%E5%85%88%E5%8F%91%E4%B8%80%E7%89%88%E8%BF%91%E4%BC%BC%E7%BB%93%E6%9E%9C%22%5D%0A%20%20SKEW%20--%3E%20LATE%5B%22%E8%BF%9F%E5%88%B0%E8%AE%B0%E5%BD%95%E5%88%B0%E8%BE%BE%22%5D%0A%20%20LATE%20--%3E%20REV%5B%22%E8%BF%BD%E5%8A%A0%E4%BF%AE%E8%AE%A2%EF%BC%9Achangelog%20%E5%87%BA%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20REV%20--%3E%20DOWN%5B%22%E4%B8%8B%E6%B8%B8%E6%B6%88%E8%B4%B9%E4%BF%AE%E8%AE%A2%E6%88%96%E8%AF%BB%E5%BF%AB%E7%85%A7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">直觉类比：处理时间像快递的签收时间，事件时间像包裹上写的发货日期——站点拥堵时两者能差好几天。要回答「哪天下单的」，就得按包裹上的日期记账；按签收日记账，答案就会随物流快慢漂移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义窗口与进度声明（后两课），不处理故障语义（第四课），也不把「流处理」绑定到某个引擎。微批是本模型的一个工程点：用小的处理时间片近似连续流动，实现简单，换掉的是事件时间表达力。更不要把套接字 read 循环叫流系统：没有可重放输入、托管状态与恢复协议，它只是消费者，挂了就丢。后课默认：谈到流聚合，输入可重放、记录带事件时间、结果带修订，这三条已经成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流处理的前提是无界：计算永远在进行，结果以 changelog 持续修正。</li><li>事件时间属于数据，处理时间属于机器；二者之差无上界，必须分开陈述。</li><li>可重放输入是故障恢复的前提，分区追加日志因此是标准源。</li><li>正确性换延迟：早发射加修订，是模型的一部分，不是权宜之计。</li><li>出处：Akidau et al., MillWheel, VLDB 2013；The Dataflow Model, VLDB 2015；Kreps, Narkhede and Rao, 2011。</li></ul>',5))])}const u=i(p,[["render",m]]);export{g as __pageData,u as default};
